def even_binomial_Coeff_Sum(n):
    total = 0
    for k in range(0, n + 1, 2):
        # Calculate the binomial coefficient C(n, k)
        c = 1
        if k > n - k:
            k = n - k  # Take advantage of symmetry to reduce computation
        for i in range(1, k + 1):
            c = c * (n - k + i) // i
        total += c
    return total
